import{_ as i,l as s,o as r,c as l,v as e,p as n,x as o,d as h,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"相关互换","description":"","frontmatter":{"title":"相关互换","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/correlation-swap.md","filePath":"quant/correlation-swap.md","lastUpdated":1789023840000}'),d={name:"quant/correlation-swap.md"};function _(m,a,B,c,u,A){const t=s("Mermaid");return r(),l("div",null,[a[1]||(a[1]=e('<h1 id="相关互换" tabindex="-1">相关互换 <a class="header-anchor" href="#相关互换" aria-label="Permalink to &quot;相关互换&quot;">​</a></h1><div class="epigraph"><p>相关互换交换已实现相关与约定执行价；它不是两份方差互换的差，也不是分散交易的残差记账。</p><footer>—— 隐含相关与分散见指数/成分期权实务；相关互换合约定义见经纪商确认书与 Bossu 等对 correlation trading 的整理</footer></div><p><a href="/quant/gamma-swap">上一课</a>还在单资产二次变差的加权。相关互换的对象是 <strong>\\(\\rho\\)</strong>：一对或一篮子资产的已实现相关，对一个固定执行价 \\(K_\\rho\\) 结算。主干 <a href="/quant/dispersion-trade">分散交易</a> 已经用指数期权对成分期权交易隐含相关。本课缺口是：把相关做成互换后，支付、年化、协方差估计窗口与分散的 Vega 残差如何分开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两资产已实现相关 \\(\\hat\\rho=\\frac{\\sum r^{(1)}r^{(2)}}{\\sqrt{\\sum(r^{(1)})^2\\sum(r^{(2)})^2}}\\)。相关互换支付与 \\(\\hat\\rho-K_\\rho\\) 成正比。看起来像「把分散里的 \\(\\rho\\) 单拎出来」，但分散交易同时暴露于指数与成分的波动水平、权重漂移、分红与借券；相关互换把波动水平尽量除掉，只留相关。问题是已实现相关的估计：同步、隔夜、时区、以及零波动日子会让分母不稳定。把相关互换当「分散的线性化」，会在 vol 崩溃时发现互换与期权分散的 PnL 并不平行。</p><p>篮子相关互换常用等权平均成对 \\(\\rho_{ij}\\)，或对指数方差公式反推一个平均相关。两种 \\(K_\\rho\\) 不是同一个数。</p><h3 id="隐含相关不是已实现相关的无偏预报" tabindex="-1">隐含相关不是已实现相关的无偏预报 <a class="header-anchor" href="#隐含相关不是已实现相关的无偏预报" aria-label="Permalink to &quot;隐含相关不是已实现相关的无偏预报&quot;">​</a></h3><p>从指数与成分期权反推的 \\(\\rho_{\\mathrm{imp}}\\) 含相关风险溢价、跳跃共跳与流动性。相关互换的公平 \\(K_\\rho\\) 即使在无套利叙述里，也不等于历史 \\(\\hat\\rho\\)。交易的是溢价是否过厚，不是「相关会回归到历史均值」这一句。</p><p><span class="marginnote">相关互换通常不交换协方差。协方差互换吃波动水平；相关把水平除掉。Vol 突然上升且相关不变时，协方差互换大亏或大赚，相关互换可以几乎不动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合约写清：收益频率（日/周）、是否重叠、哪些交易日、是否用外汇 quanto 调整后的收益、篮子如何平均。估值：用高斯 copula 或因子模型生成风险中性已实现相关的期望，边际波动来自各资产方差互换或香草；更稳的是把相关互换当分散组合的近似对冲去标定。对冲：短指数变分、长成分变分（分散），再把剩余的 vol 水平用方差互换削掉，尽量留下 \\(\\rho\\)。残差来自权重、跳、以及相关的高阶（相关的波动）。</p><p><a href="/quant/basket-rainbow">彩虹与篮子</a> 的期权对 \\(\\rho\\) 的敏感是非线性的；相关互换更接近线性 \\(\\rho\\)。两者不要用同一套希腊值报告。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指数方差 \\(\\sigma_I^2\\approx\\sum w_i^2\\sigma_i^2+2\\sum_{i\\lt j}w_i w_j\\rho_{ij}\\sigma_i\\sigma_j\\)。固定 \\(\\sigma_i\\) 时，\\(\\rho\\) 升则 \\(\\sigma_I\\) 升。分散卖指数波动、买成分波动，近似卖 \\(\\rho_{\\mathrm{imp}}\\)。相关互换直接在 \\(\\rho\\) 上结算，省掉把 \\(\\sigma_i\\) 波动当噪声的那一层，但失去了期权凸性：相关到 1 附近，期权分散还有 vega 凸性，互换是线性的。</p>',14)),(r(),n(E,null,{default:o(()=>[p(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Imp%5B%22%E6%8C%87%E6%95%B0%E4%B8%8E%E6%88%90%E5%88%86%E6%9C%9F%E6%9D%83%22%5D%20--%3E%20RhoI%5B%22%E9%9A%90%E5%90%AB%E7%9B%B8%E5%85%B3%22%5D%0A%20%20Real%5B%22%E5%90%8C%E6%AD%A5%E6%94%B6%E7%9B%8A%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20RhoR%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E7%9B%B8%E5%85%B3%22%5D%0A%20%20RhoI%20--%3E%20Disp%5B%22%E5%88%86%E6%95%A3%E4%BA%A4%E6%98%93%20%E4%BB%8D%E5%90%AB%20vol%20%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20RhoR%20--%3E%20Swap%5B%22%E7%9B%B8%E5%85%B3%E4%BA%92%E6%8D%A2%20%E6%94%AF%E4%BB%98%20%CF%81-K%22%5D%0A%20%20Disp%20--%3E%20Hedge%5B%22%E7%94%A8%E5%8F%98%E5%88%86%E5%AF%B9%E5%86%B2%E4%BA%92%E6%8D%A2%22%5D%0A%20%20Swap%20--%3E%20Hedge%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>异步报价让日度相关偏低（Epps），高频相关另算，见计量课的刷新时间。危机里相关冲向 1，互换卖方像在卖深度尾部，线性名义会迅速变成非线性经济暴露。单名停牌、除权、指数调样都会打断收益序列，合同需要后备定义。</p><p>本课不提供「如何把相关推高/推低」的交易清单。对象是合约与对冲分解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>相关互换结算已实现 \\(\\rho\\) 对 \\(K_\\rho\\)，与协方差互换、与期权分散都不是同一工具。</li><li>隐含相关含溢价；公平执行价不是历史均值。</li><li>用分散对冲时要再削掉 vol 水平，并接受权重与跳的残差。</li><li>出处：分散与隐含相关见指数期权实务；Epps 效应见 Epps, <em>Journal of the American Statistical Association</em>, 1979。</li></ul>',5))])}const g=i(d,[["render",_]]);export{q as __pageData,g as default};
